INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $pilot$PT156-S4-Q10$pilot$, 156, 4, 10, $pilot$Paradox$pilot$, $pilot$While the population of city X is approximately one-half
